    if ((await provider.getNetwork()).chainId !== CHAIN_ID) throw new Error(`Switch your wallet to chain ${CHAIN_ID}`);
    const nextSigner = await provider.getSigner(), { nonce } = await (await fetch(`${API}/api/nonce`, { credentials: "include" })).json();
    const message = `Atlas sign-in\nDomain: ${location.host}\nChain: ${CHAIN_ID}\nNonce: ${nonce}`;
    const response = await fetch(`${API}/api/login`, { method: "POST", credentials: "include", headers: jsonHeaders(), body: JSON.stringify({ message, signature: await nextSigner.signMessage(message) }) });
    const result = await response.json(); if (!response.ok) throw new Error(result.error || "Wallet sign-in failed");
