      <section><div className="section-heading"><div><p className="eyebrow">CATALOG</p><h2>Models</h2></div><span className="meta">{total} result{total === 1 ? "" : "s"}</span></div>{loadError && <p className="error">{loadError}</p>}{!loadError && models.length === 0 && <p className="meta">No models match these filters.</p>}<div className="grid">{models.map((model) => <ModelCard key={model.id} model={model} account={account} owned={Boolean(licensed[model.id] || fiatLicensed[model.id])} onchainOwned={Boolean(licensed[model.id])} fiatOwned={Boolean(fiatLicensed[model.id])} canChain={Boolean(signer && authType === "wallet" && isAddress(account || ""))} alreadyRated={rated[model.id]} favorite={Boolean(favorites[model.id])} busy={busy} buy={buy} rate={rate} token={token} note={note} run={run} onPaid={load} onFavorite={() => favorite(model)} />)}</div><div className="row pager"><button className="ghost" disabled={busy || page === 0} onClick={() => setPage((p) => p - 1)}>Previous</button><span className="meta">Page {page + 1} of {Math.max(1, Math.ceil(total / PAGE_SIZE))}</span><button className="ghost" disabled={busy || (page + 1) * PAGE_SIZE >= total} onClick={() => setPage((p) => p + 1)}>Next</button></div></section>
