function AuthPanel({ onAuthenticated, onClose, busy, run }) {
  const [mode, setMode] = useState("login"), [email, setEmail] = useState(""), [password, setPassword] = useState(""), [confirm, setConfirm] = useState("");
  const submit = (event) => { event.preventDefault(); run(async () => { if (mode === "register" && password !== confirm) throw new Error("Passwords do not match"); const response = await post(`/api/auth/${mode}`, null, { email, password }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "Unable to authenticate"); onAuthenticated(result); setPassword(""); setConfirm(""); }); };
  return <section className="auth-panel"><div className="section-heading"><div><p className="eyebrow">ATLAS ACCOUNT</p><h2>{mode === "login" ? "Sign in with Gmail" : "Create your Atlas account"}</h2><p className="auth-copy">Use a Gmail address or any email address with a password. You can then buy models using INR/UPI; connect MetaMask separately for blockchain purchases and creator publishing.</p></div>{onClose && <button className="ghost" type="button" onClick={onClose}>Close</button>}</div><div className="row auth-tabs"><button type="button" className={mode === "login" ? "tab active" : "tab"} onClick={() => setMode("login")}>Sign in</button><button type="button" className={mode === "register" ? "tab active" : "tab"} onClick={() => setMode("register")}>Create account</button></div><form onSubmit={submit}><input required type="email" autoComplete="email" placeholder="you@gmail.com" value={email} onChange={(e) => setEmail(e.target.value)} aria-label="Gmail or email address" /><input required type="password" minLength={8} maxLength={128} autoComplete={mode === "login" ? "current-password" : "new-password"} placeholder="Password (8+ characters)" value={password} onChange={(e) => setPassword(e.target.value)} aria-label="Password" />{mode === "register" && <input required type="password" minLength={8} maxLength={128} autoComplete="new-password" placeholder="Confirm password" value={confirm} onChange={(e) => setConfirm(e.target.value)} aria-label="Confirm password" />}<button disabled={busy}>{mode === "login" ? "Sign in" : "Create account"}</button></form><p className="hint">This is email/password authentication, not Google OAuth. Never reuse your wallet private key as your password.</p></section>;
}

function AuthPanelV2({ onAuthenticated, onClose, busy, run, note }) {
  const initialResetToken = new URLSearchParams(window.location.search).get("reset") || "";
  const [mode, setMode] = useState(initialResetToken ? "reset-confirm" : "login"), [email, setEmail] = useState(""), [password, setPassword] = useState(""), [confirm, setConfirm] = useState(""), [resetToken, setResetToken] = useState(initialResetToken);
  const submit = (event) => { event.preventDefault(); run(async () => {
    if ((mode === "register" || mode === "reset-confirm") && password !== confirm) throw new Error("Passwords do not match");
    if (mode === "reset-request") {
      const response = await post("/api/auth/password-reset/request", null, { email }), result = await response.json();
      if (!response.ok) throw new Error(result.error || "Unable to request a password reset");
      note(result.developmentResetUrl ? `Development reset link: ${result.developmentResetUrl}` : result.message);
      setMode("login"); return;
    }
    if (mode === "reset-confirm") {
      const response = await post("/api/auth/password-reset/confirm", null, { token: resetToken, password }), result = await response.json();
      if (!response.ok) throw new Error(result.error || "Unable to reset password");
      window.history.replaceState({}, "", window.location.pathname); onAuthenticated(result); setPassword(""); setConfirm(""); return;
    }
    const endpoint = mode === "register" ? "/api/auth/register" : "/api/auth/login";
    const response = await post(endpoint, null, { email, password }), result = await response.json();
    if (!response.ok) throw new Error(result.error || "Unable to authenticate");
    onAuthenticated(result); setPassword(""); setConfirm("");
  }); };
  const resetMode = mode === "reset-request" || mode === "reset-confirm";
  const title = mode === "login" ? "Sign in to Atlas" : mode === "register" ? "Create your Atlas account" : mode === "reset-confirm" ? "Choose a new password" : "Reset your Atlas password";
  return <section className="auth-panel"><div className="section-heading"><div><p className="eyebrow">ATLAS ACCOUNT</p><h2>{title}</h2><p className="auth-copy">Sign in with Google or use your Gmail/email and password. INR/UPI buyers do not need a wallet; creators still connect a wallet for publishing and blockchain earnings.</p></div>{onClose && <button className="ghost" type="button" onClick={onClose}>Close</button>}</div>{!resetMode && <><div className="row auth-tabs"><button type="button" className={mode === "login" ? "tab active" : "tab"} onClick={() => setMode("login")}>Sign in</button><button type="button" className={mode === "register" ? "tab active" : "tab"} onClick={() => setMode("register")}>Create account</button></div><a className="google-button" href={`${API}/api/auth/google`}>Continue with Google</a></>}{resetMode && <button type="button" className="link-button auth-back" onClick={() => setMode("login")}>← Back to sign in</button>}<form onSubmit={submit}>{mode !== "reset-confirm" && <input required type="email" autoComplete="email" placeholder="you@gmail.com" value={email} onChange={(e) => setEmail(e.target.value)} aria-label="Gmail or email address" />}{mode !== "reset-request" && mode !== "reset-confirm" && <input required type="password" minLength={8} maxLength={128} autoComplete={mode === "login" ? "current-password" : "new-password"} placeholder="Password (8+ characters)" value={password} onChange={(e) => setPassword(e.target.value)} aria-label="Password" />}{mode === "register" && <input required type="password" minLength={8} maxLength={128} autoComplete="new-password" placeholder="Confirm password" value={confirm} onChange={(e) => setConfirm(e.target.value)} aria-label="Confirm password" />}{mode === "reset-request" && <button disabled={busy}>Send reset link</button>}{mode === "reset-confirm" && <><input required type="password" minLength={8} maxLength={128} autoComplete="new-password" placeholder="New password (8+ characters)" value={password} onChange={(e) => setPassword(e.target.value)} aria-label="New password" /><input required type="password" minLength={8} maxLength={128} autoComplete="new-password" placeholder="Confirm new password" value={confirm} onChange={(e) => setConfirm(e.target.value)} aria-label="Confirm new password" /><button disabled={busy}>Update password</button></>}{!resetMode && <button disabled={busy}>{mode === "login" ? "Sign in with email" : "Create account"}</button>}</form>{mode === "login" && <button type="button" className="link-button auth-reset" onClick={() => setMode("reset-request")}>Forgot password?</button>}<p className="hint">Google sign-in verifies the Google account email. Password accounts require email verification in production.</p></section>;
}

function ModelCard({ model, account, owned, onchainOwned, fiatOwned, canChain, alreadyRated, favorite, busy, buy, rate, token, note, run, onPaid, onFavorite }) {
  const [input, setInput] = useState(""), [out, setOut] = useState(null), [comments, setComments] = useState([]), [comment, setComment] = useState(""), [expanded, setExpanded] = useState(false);
  const isCreator = account && model.creator.toLowerCase() === account.toLowerCase();
  const avg = model.ratingCount !== "0" ? (Number(model.ratingSum) / Number(model.ratingCount)).toFixed(1) : "-";
  const infer = () => run(async () => { const response = await post(`/api/infer/${model.id}`, token, { input }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setOut(result); });
  const payInr = () => run(async () => {
    if (!window.Razorpay) throw new Error("Razorpay Checkout did not load. Check your network or Content-Security-Policy");
    const orderResponse = await post("/api/payments/order", token, { modelId: model.id }), order = await orderResponse.json();
    if (!orderResponse.ok) throw new Error(order.error || "Could not create INR order");
    await new Promise((resolve, reject) => {
      const checkout = new window.Razorpay({ key: order.keyId, amount: order.amount, currency: order.currency, name: "Atlas", description: order.description, order_id: order.orderId,
        handler: async (response) => { try { const verifyResponse = await post("/api/payments/verify", token, { modelId: model.id, ...response }); const result = await verifyResponse.json(); if (!verifyResponse.ok) throw new Error(result.error || "Payment verification failed"); note("INR payment captured; model access granted"); onPaid(); resolve(); } catch (error) { reject(error); } },
        modal: { ondismiss: () => reject(new Error("INR payment cancelled")) }, theme: { color: "#f2b84b" } });
      checkout.on("payment.failed", (response) => reject(new Error(response.error?.description || "INR payment failed"))); checkout.open();
    });
  });
  const download = () => run(async () => {
    let urlPath = `/api/artifact/${model.contentHash.slice(2)}?model=${model.id}`, downloadName = `${model.name.replace(/[^a-z0-9._-]/gi, "_")}-${model.contentHash.slice(2, 10)}`;
    if (model.source?.type === "huggingface") {
      const filesResponse = await fetch(`${API}/api/huggingface/files/${model.id}`, { credentials: "include", headers: jsonHeaders(token) }), filesResult = await filesResponse.json();
      if (!filesResponse.ok) throw new Error(filesResult.error || "Hugging Face weights are unavailable");
      const files = filesResult.files || []; if (!files.length) throw new Error("No downloadable weight files were found");
      const defaultFile = files[0].name, selectedName = files.length === 1 ? defaultFile : window.prompt(`Choose a weight file:\n${files.map((file) => file.name).join("\n")}`, defaultFile);
      if (!selectedName) return; const selected = files.find((file) => file.name === selectedName); if (!selected) throw new Error("Choose one of the listed weight files");
      urlPath = `/api/huggingface/download/${model.id}?file=${encodeURIComponent(selected.name)}`; downloadName = selected.name.split("/").pop();
    }
    const response = await fetch(`${API}${urlPath}`, { credentials: "include", headers: jsonHeaders(token) }); if (!response.ok) { const result = await response.json().catch(() => ({})); throw new Error(result.error || "Download unavailable"); } const blob = await response.blob(), url = URL.createObjectURL(blob), link = document.createElement("a"); link.href = url; link.download = downloadName; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url);
  });
  const configure = (provider) => run(async () => { const body = provider === "huggingface" ? { provider, repo: model.hfRepo } : { provider, url: prompt("Inference endpoint URL (HTTPS required in production)") }; if (!body.url && provider !== "huggingface") return; const response = await post(`/api/endpoint/${model.id}`, token, body); const result = await response.json(); if (!response.ok) throw new Error(result.error); note(provider === "huggingface" ? "GPU-capable Hugging Face inference enabled" : "Creator endpoint saved"); });
  const loadComments = async () => { const response = await fetch(`${API}/api/models/${model.id}/comments`, { credentials: "include" }); const result = await response.json(); if (response.ok) setComments(result.comments || []); setExpanded(true); };
  const addComment = () => run(async () => { const response = await post(`/api/models/${model.id}/comments`, token, { body: comment }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setComments((old) => [result.comment, ...old]); setComment(""); setExpanded(true); });
  const report = () => run(async () => { const details = prompt("What should Atlas review about this model?"); if (!details) return; const response = await post("/api/reports", token, { modelId: model.id, reason: "community-report", details }); const result = await response.json(); if (!response.ok) throw new Error(result.error); note("Report submitted to Atlas moderation"); });
  return <article className="card"><div className="card-top"><div><h3>{model.name}</h3><div className="meta">by {short(model.creator)} · {model.sales} sales · ★ {avg} ({model.ratingCount})</div></div><button className="icon-button" aria-label={favorite ? "Remove from saved models" : "Save model"} onClick={onFavorite}>{favorite ? "★" : "☆"}</button></div><div className="badges"><span className="badge">{model.source?.type === "huggingface" ? "Hugging Face" : "Creator upload"}</span>{model.license && <span className="badge">{model.license}</span>}{model.priceInr && <span className="badge">UPI ₹{Number(model.priceInr).toLocaleString("en-IN")}</span>}{model.source?.pipelineTag && <span className="badge">{model.source.pipelineTag}</span>}</div><p className="description">{model.description || "A creator-published AI model available through Atlas."}</p><div className="meta">{model.active ? "Active" : "Delisted"} · {model.tags?.slice(0, 5).join(" · ") || "general AI"}</div><div className="price">{formatEther(model.price)} ETH <small>{inr(model.price)}{model.priceInr ? ` · UPI ₹${Number(model.priceInr).toLocaleString("en-IN")}` : ""}</small></div>{model.metadataURI?.startsWith("http") && <a className="meta" href={model.metadataURI} target="_blank" rel="noreferrer">View licence and model metadata ↗</a>}{!account && <div className="meta">Sign in to buy with INR/UPI, or connect a wallet for an on-chain purchase</div>}{account && !owned && model.active && <div className="row"><button disabled={busy || !canChain} onClick={() => buy(model)}>{canChain ? `Buy on-chain · ${formatEther(model.price)} ETH` : "Connect wallet for ETH purchase"}</button>{model.priceInr && <button className="ghost" disabled={busy} onClick={payInr}>Pay with UPI · ₹{Number(model.priceInr).toLocaleString("en-IN")}</button>}</div>}{owned && <><div className="row"><span className="badge">{fiatOwned && !onchainOwned ? "INR access" : "On-chain licence"}</span><button className="ghost" disabled={busy} onClick={download}>{model.source?.type === "huggingface" ? "Download HF weights" : "Download weights"}</button>{isCreator && <button className="ghost" disabled={busy} onClick={() => configure(model.source?.type === "huggingface" ? "huggingface" : "creator")}>{model.source?.type === "huggingface" ? "Enable GPU inference" : "Set endpoint"}</button>}</div><textarea rows={2} placeholder="Ask the licensed model something…" value={input} onChange={(e) => setInput(e.target.value)} aria-label="Model input" /><div className="row"><button disabled={busy || !input} onClick={infer}>Run inference</button>{isCreator ? <span className="meta">Creator controls enabled</span> : !onchainOwned ? <span className="meta">Rate after an on-chain licence purchase</span> : alreadyRated ? <span className="meta">Rating submitted</span> : [1, 2, 3, 4, 5].map((score) => <button key={score} className="ghost" disabled={busy} onClick={() => rate(model, score)} aria-label={`Rate ${score}`}>{score}</button>)}</div>{out && <pre>{JSON.stringify(out, null, 2)}</pre>}</>}<div className="card-actions"><button className="link-button" onClick={() => expanded ? setExpanded(false) : loadComments()}>Community discussion</button>{token && <button className="link-button" onClick={report}>Report</button>}</div>{expanded && <div className="comments">{comments.length === 0 ? <span className="meta">No comments yet.</span> : comments.map((item) => <div className="comment" key={item.id}><span className="meta">{short(item.user)}</span><div>{item.body}</div></div>)}{token && <div className="comment-form"><input value={comment} onChange={(e) => setComment(e.target.value)} maxLength={1000} placeholder="Share a useful note" aria-label="Comment" /><button className="ghost" disabled={busy || !comment.trim()} onClick={addComment}>Post</button></div>}</div>}</article>;
}

function ListForm({ token, run, busy, signer, contract, note, reload }) {
  const empty = { name: "", description: "", version: "1.0.0", price: "0.05", priceInr: "", file: null, contentHash: "", repo: "", tags: "", license: "mit", licenseUrl: "", provenanceUrl: "", licenseDocument: null, provenanceDocument: null, purpose: "", trainingData: "", limitations: "", intendedUsers: "", riskNotes: "", ownership: false, safety: false, responsibility: false };
  const [mode, setMode] = useState("upload"), [f, setF] = useState(empty), [verification, setVerification] = useState(null);
  const set = (key, value) => setF((old) => ({ ...old, [key]: value }));
  const card = { purpose: f.purpose, trainingData: f.trainingData, limitations: f.limitations, intendedUsers: f.intendedUsers, riskNotes: f.riskNotes };
  const submit = (event) => { event.preventDefault(); run(async () => {
    if (!f.ownership || !f.safety || !f.responsibility) throw new Error("Accept all creator verification declarations before publishing");
    let hash = "", uri = "", license = f.license, licenseUrl = f.licenseUrl.trim(), metadataId = "", sourceType = mode === "huggingface" ? "huggingface" : "direct";
    if (mode === "huggingface") {
      const response = await post("/api/huggingface/import", token, { repo: f.repo, name: f.name, description: f.description, priceInr: f.priceInr, tags: f.tags.split(",").map((v) => v.trim()).filter(Boolean), provenanceUrl: f.provenanceUrl, modelCard: card });
      const result = await response.json(); if (!response.ok) throw new Error(result.error); hash = result.contentHash; uri = result.metadataURI; metadataId = result.id; license = result.license; licenseUrl = result.licenseUrl || licenseUrl;
    } else {
      if (!f.file) throw new Error("Select the model file so Atlas can scan it and calculate its content hash");
      const form = new FormData(); form.append("file", f.file); const response = await fetch(`${API}/api/upload`, { method: "POST", credentials: "include", headers: authHeaders(token), body: form }); const uploadResult = await response.json(); if (!response.ok) throw new Error(uploadResult.error); hash = uploadResult.contentHash;
      const metadata = await post("/api/metadata", token, { name: f.name, description: f.description, version: f.version, artifactHash: hash, priceInr: f.priceInr, inputSchema: { type: "string" }, outputSchema: { type: "object" }, tags: f.tags.split(",").map((v) => v.trim()).filter(Boolean), license, licenseUrl, provenanceUrl: f.provenanceUrl, modelCard: card });
      const metadataResult = await metadata.json(); if (!metadata.ok) throw new Error(metadataResult.error); uri = metadataResult.metadataURI; metadataId = metadataResult.id;
    }
    if (!/^0x[0-9a-fA-F]{64}$/.test(hash) || !metadataId) throw new Error("Atlas could not create a verifiable model manifest");
    const proofRequired = ["commercial", "proprietary", "custom"].includes(license);
    if (proofRequired && !f.licenseDocument) throw new Error("Upload the licence document for a commercial, proprietary, or custom licence");
    const prepareResponse = await post("/api/model-verifications/prepare", token, { metadataId, artifactHash: hash, license, licenseUrl, provenanceUrl: f.provenanceUrl, modelCard: card, sourceType, declarations: { ownership: f.ownership, safety: f.safety, responsibility: f.responsibility } });
    const prepared = await prepareResponse.json(); if (!prepareResponse.ok) throw new Error(prepared.error || "Model verification could not be prepared");
    setVerification(prepared);
    const uploadEvidence = async (file, kind) => { if (!file) return; const body = new FormData(); body.append("file", file); body.append("kind", kind); const response = await fetch(`${API}/api/model-verifications/${prepared.verificationId}/evidence`, { method: "POST", credentials: "include", headers: authHeaders(token), body }); const result = await response.json(); if (!response.ok) throw new Error(result.error || `${kind} evidence upload failed`); };
    await uploadEvidence(f.licenseDocument, "license"); await uploadEvidence(f.provenanceDocument, "provenance");
    const signature = await signer.signMessage(prepared.message);
    const attestResponse = await post(`/api/model-verifications/${prepared.verificationId}/attest`, token, { signature });
    const attested = await attestResponse.json(); if (!attestResponse.ok) throw new Error(attested.error || "Model verification failed");
    if (attested.status !== "approved") { note("Creator attestation saved; Atlas moderation must review the evidence before listing"); return; }
    await (await contract().listModel(f.name || "Imported Atlas model", uri, hash, parseEther(f.price))).wait();
    note(`Model attested and listed on-chain under the ${license} licence`); setF(empty); setVerification(null); reload();
  }); };
  const field = (key, placeholder, required = true) => <textarea required={required} maxLength={1500} rows={2} placeholder={placeholder} value={f[key]} onChange={(e) => set(key, e.target.value)} aria-label={placeholder} />;
  const proofRequired = ["commercial", "proprietary", "custom"].includes(f.license);
  return <section className="builder"><div className="section-heading"><div><p className="eyebrow">CREATOR STUDIO</p><h2>Publish an AI model</h2><p className="hint">Atlas records creator attestation and moderation checks. It cannot automatically prove legal ownership.</p></div><span className="badge">Trust review required</span></div><div className="row tabs"><button className={mode === "upload" ? "tab active" : "tab"} onClick={() => setMode("upload")} type="button">Upload your model</button><button className={mode === "huggingface" ? "tab active" : "tab"} onClick={() => setMode("huggingface")} type="button">Import from Hugging Face</button></div><form onSubmit={submit}>{mode === "huggingface" ? <><input required placeholder="Hugging Face repo, e.g. google/flan-t5-small" value={f.repo} onChange={(e) => set("repo", e.target.value)} aria-label="Hugging Face repository" /><p className="hint">Atlas checks the upstream licence and records the exact repository revision. Repositories without an approved redistribution licence are rejected.</p></> : <input required type="file" accept=".onnx,.safetensors,.gguf,.tflite" onChange={(e) => set("file", e.target.files?.[0] || null)} aria-label="Model file" />}<input required maxLength={80} placeholder="Model name" value={f.name} onChange={(e) => set("name", e.target.value)} aria-label="Model name" /><textarea required maxLength={2000} rows={3} placeholder="What can this model help an MSME do?" value={f.description} onChange={(e) => set("description", e.target.value)} aria-label="Model description" /><input maxLength={200} placeholder="Tags: hindi, agriculture, vision" value={f.tags} onChange={(e) => set("tags", e.target.value)} aria-label="Tags" /><div className="price-fields"><input required type="number" step="0.001" min="0" placeholder="Blockchain price in ETH" value={f.price} onChange={(e) => set("price", e.target.value)} aria-label="Price in ETH" /><input required type="number" step="0.01" min="1" placeholder="INR/UPI price in rupees" value={f.priceInr} onChange={(e) => set("priceInr", e.target.value)} aria-label="Price in Indian rupees" /></div><div className="verification-fields"><h3>Licence and provenance</h3><select required value={f.license} onChange={(e) => set("license", e.target.value)} aria-label="Model licence"><option value="mit">MIT</option><option value="apache-2.0">Apache-2.0</option><option value="bsd-3-clause">BSD-3-Clause</option><option value="cc-by-4.0">CC-BY-4.0</option><option value="openrail">OpenRAIL</option><option value="commercial">Commercial licence</option><option value="proprietary">Proprietary</option><option value="custom">Custom approved licence</option></select><input type="url" placeholder="HTTPS licence/proof URL" value={f.licenseUrl} onChange={(e) => set("licenseUrl", e.target.value)} aria-label="Licence proof URL" /><input type="url" placeholder="HTTPS source/code/provenance URL (optional)" value={f.provenanceUrl} onChange={(e) => set("provenanceUrl", e.target.value)} aria-label="Provenance URL" /><label className="upload-button">Licence document {proofRequired ? "(required)" : "(optional)"}<input type="file" accept=".pdf,.txt,.md,.json,image/png,image/jpeg,image/webp" required={proofRequired} onChange={(e) => set("licenseDocument", e.target.files?.[0] || null)} /></label><label className="upload-button">Provenance evidence (optional)<input type="file" accept=".pdf,.txt,.md,.json,image/png,image/jpeg,image/webp" onChange={(e) => set("provenanceDocument", e.target.files?.[0] || null)} /></label><p className="hint">Commercial/custom licences and provenance evidence go to human moderation. Exact hashes are checked; semantic plagiarism still needs review.</p>{field("purpose", "Intended purpose and use case")}{field("trainingData", "Training data source and permissions")}{field("limitations", "Known limitations, bias, or failure cases")}{field("intendedUsers", "Intended users and industries")}{field("riskNotes", "Safety or risk notes (optional)", false)}</div><div className="verification-checks"><label><input type="checkbox" checked={f.ownership} onChange={(e) => set("ownership", e.target.checked)} /> I own this model or have permission to distribute it.</label><label><input type="checkbox" checked={f.safety} onChange={(e) => set("safety", e.target.checked)} /> I have disclosed known safety, bias, privacy, and misuse risks.</label><label><input type="checkbox" checked={f.responsibility} onChange={(e) => set("responsibility", e.target.checked)} /> I accept responsibility for the licence and information submitted.</label><p className="hint">MetaMask signs these exact details. The signature proves wallet control and attestation, not legal ownership.</p></div>{verification?.status === "awaiting_signature" && <p className="notice">Waiting for wallet signature…</p>}<button disabled={busy}>{mode === "huggingface" ? "Attest and submit imported model" : "Attest and submit model"}</button></form></section>;
}

function ProfileForm({ token, run, busy, note }) {
  const [form, setForm] = useState({ displayName: "", bio: "", language: "", msme: "", website: "", githubUrl: "", avatarUrl: "" });
  const [avatarFile, setAvatarFile] = useState(null), [preview, setPreview] = useState("");
  useEffect(() => { fetch(`${API}/api/creator-profile`, { credentials: "include", headers: jsonHeaders(token) }).then(async (response) => response.ok ? response.json() : null).then((result) => { if (result?.profile) setForm((old) => ({ ...old, ...result.profile })); }).catch(() => {}); }, [token]);
  const set = (key, value) => setForm((old) => ({ ...old, [key]: value }));
  const chooseAvatar = (event) => { const file = event.target.files?.[0]; if (!file) return; setAvatarFile(file); setPreview(URL.createObjectURL(file)); };
  const submit = (event) => { event.preventDefault(); run(async () => { const response = await post("/api/creator-profile", token, form); const result = await response.json(); if (!response.ok) throw new Error(result.error); if (avatarFile) { const body = new FormData(); body.append("avatar", avatarFile); const avatarResponse = await fetch(`${API}/api/creator-profile/avatar`, { method: "POST", credentials: "include", headers: authHeaders(token), body }); const avatarResult = await avatarResponse.json(); if (!avatarResponse.ok) throw new Error(avatarResult.error || "Profile photo upload failed"); set("avatarUrl", avatarResult.avatarUrl); setAvatarFile(null); } setForm((old) => ({ ...old, ...(result.profile || {}) })); note("Creator profile updated"); }); };
  return <section className="profile"><div className="section-heading"><div><p className="eyebrow">CREATOR IDENTITY</p><h2>Update your creator profile</h2><p className="hint">This profile appears beside your models and in the Atlas community.</p></div></div><form onSubmit={submit}><div className="profile-photo-row"><div className="avatar large">{(preview || form.avatarUrl) ? <img src={preview || form.avatarUrl} alt="Creator profile" onError={(e) => { e.currentTarget.style.display = "none"; }} /> : <span>{(form.displayName || "A").slice(0, 1).toUpperCase()}</span>}</div><label className="upload-button">Choose profile photo<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={chooseAvatar} /></label><span className="hint">PNG, JPG, WebP, or GIF up to 2 MB</span></div><input required maxLength={80} placeholder="Display name or studio" value={form.displayName} onChange={(e) => set("displayName", e.target.value)} aria-label="Creator display name" /><textarea maxLength={500} placeholder="Your mission and expertise" value={form.bio} onChange={(e) => set("bio", e.target.value)} aria-label="Creator bio" /><div className="price-fields"><input placeholder="Languages: English, Hindi, Tamil…" value={form.language} onChange={(e) => set("language", e.target.value)} aria-label="Creator languages" /><input placeholder="MSME or industry served" value={form.msme} onChange={(e) => set("msme", e.target.value)} aria-label="MSME or industry served" /></div><div className="price-fields"><input type="url" placeholder="https://your-studio.example" value={form.website} onChange={(e) => set("website", e.target.value)} aria-label="Creator website" /><input type="url" placeholder="https://github.com/your-name" value={form.githubUrl} onChange={(e) => set("githubUrl", e.target.value)} aria-label="GitHub profile" /></div><input type="url" placeholder="Profile photo URL (optional)" value={form.avatarUrl || ""} onChange={(e) => set("avatarUrl", e.target.value)} aria-label="Profile photo URL" /><button disabled={busy}>Save creator profile</button></form></section>;
}

function IdentityKycPanel({ token, run, busy, note }) {
  const [identity, setIdentity] = useState(null), [form, setForm] = useState({ fullName: "", country: "India", provider: "manual", providerReference: "" }), [document, setDocument] = useState(null);
  const load = useCallback(() => fetch(`${API}/api/creator-identity`, { credentials: "include", headers: jsonHeaders(token) }).then(async (response) => { const result = await response.json(); if (!response.ok) throw new Error(result.error || "Unable to load identity status"); setIdentity(result.identity); }), [token]);
  useEffect(() => { load().catch(() => {}); }, [load]);
  const set = (key, value) => setForm((old) => ({ ...old, [key]: value }));
  const submit = (event) => { event.preventDefault(); run(async () => {
    const response = await post("/api/creator-identity", token, form), result = await response.json(); if (!response.ok) throw new Error(result.error || "Identity submission failed");
    if (document) { const body = new FormData(); body.append("file", document); const uploadResponse = await fetch(`${API}/api/creator-identity/document`, { method: "POST", credentials: "include", headers: authHeaders(token), body }); const uploadResult = await uploadResponse.json(); if (!uploadResponse.ok) throw new Error(uploadResult.error || "Identity document upload failed"); setIdentity(uploadResult.identity); } else setIdentity(result.identity);
    note("Identity case submitted for Atlas moderation"); setDocument(null); load();
  }); };
  const status = identity?.status || "unverified";
  return <section className="trust-panel"><div className="section-heading"><div><p className="eyebrow">CREATOR TRUST</p><h3>Identity/KYC review</h3><p className="hint">Atlas stores review metadata and a document hash. A human or regulated KYC provider must make the final decision.</p></div><span className="badge">{status.replace("_", " ")}</span></div>{status !== "verified" && <form onSubmit={submit}><div className="price-fields"><input required maxLength={120} placeholder="Legal name" value={form.fullName} onChange={(e) => set("fullName", e.target.value)} aria-label="Legal name" /><input required maxLength={80} placeholder="Country" value={form.country} onChange={(e) => set("country", e.target.value)} aria-label="Country" /></div><div className="price-fields"><input required maxLength={80} placeholder="KYC provider or manual review" value={form.provider} onChange={(e) => set("provider", e.target.value)} aria-label="KYC provider" /><input required maxLength={200} placeholder="Provider reference / case ID" value={form.providerReference} onChange={(e) => set("providerReference", e.target.value)} aria-label="KYC provider reference" /></div><label className="upload-button">Private identity document (PDF/image)<input type="file" accept=".pdf,image/png,image/jpeg,image/webp" onChange={(e) => setDocument(e.target.files?.[0] || null)} /></label><button disabled={busy}>Submit identity review</button></form>}{status === "verified" && <p className="hint">Identity review is marked verified. This is still a moderation signal, not automatic proof of legal ownership.</p>}{status === "rejected" && <p className="error">Review reason: {identity?.rejectionReason || "See the admin decision and resubmit corrected evidence."}</p>}</section>;
}

function CreatorDashboard({ token, run, busy, note, onUpload, onToggleModel, onEditProfile }) {
  const [data, setData] = useState(null), [error, setError] = useState(null);
  const load = useCallback(() => { setError(null); return fetch(`${API}/api/creator-dashboard`, { credentials: "include", headers: jsonHeaders(token) }).then(async (response) => { const result = await response.json(); if (!response.ok) throw new Error(result.error || "Unable to load creator dashboard"); setData(result); }).catch((e) => setError(e.message)); }, [token]);
  useEffect(() => { load(); }, [load]);
  if (error) return <section className="dashboard"><p className="error">{error}</p><button className="ghost" onClick={load}>Retry</button></section>;
  if (!data) return <section className="dashboard"><p className="meta">Loading creator dashboard…</p></section>;
  const stats = data.stats || {}, profile = data.profile || {};
  const eth = formatEther(BigInt(stats.onchainEarningsWei || "0"));
  const rupees = (paise) => `₹${(Number(paise || 0) / 100).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`;
  return <section className="dashboard"><div className="section-heading"><div><p className="eyebrow">CREATOR DASHBOARD</p><h2>{profile.displayName || "Your creator studio"}</h2><p className="hint">Track models, on-chain sales, INR earnings, and your public identity.</p></div><div className="row"><button disabled={busy} onClick={onUpload}>Upload model</button><button className="ghost" disabled={busy} onClick={onEditProfile}>Edit profile</button><button className="ghost" disabled={busy} onClick={load}>Refresh</button></div></div><div className="dashboard-profile"><div className="avatar large">{profile.avatarUrl ? <img src={profile.avatarUrl} alt="Creator" /> : <span>{(profile.displayName || "A").slice(0, 1).toUpperCase()}</span>}</div><div><strong>{profile.displayName || "Atlas creator"}</strong><p className="meta">{profile.bio || "Add a short creator bio to build trust with buyers."}</p>{profile.githubUrl && <a href={profile.githubUrl} target="_blank" rel="noreferrer">GitHub profile ↗</a>}</div></div><IdentityKycPanel token={token} run={run} busy={busy} note={note} /><div className="stats dashboard-stats"><div><strong>{stats.modelCount}</strong><span>Published models</span></div><div><strong>{stats.onchainSales}</strong><span>On-chain sales</span></div><div><strong>{eth} ETH</strong><span>Withdrawable earnings</span></div><div><strong>{rupees(stats.fiatCreatorNetPaise)}</strong><span>INR creator earnings</span></div></div><div className="section-heading dashboard-subheading"><div><p className="eyebrow">YOUR MODELS</p><h3>Published catalogue</h3></div><span className="meta">{stats.fiatPayments} INR payment{stats.fiatPayments === 1 ? "" : "s"}</span></div>{data.models.length === 0 ? <p className="meta">No models listed yet. Connect your wallet and publish your first model from the Marketplace.</p> : <div className="grid">{data.models.map((model) => <div className="card compact-card" key={model.id}><div className="card-top"><div><h3>{model.name}</h3><p className="meta">{model.sales} on-chain sales · {formatEther(BigInt(model.price))} ETH</p></div><span className="badge">{model.active ? "Active" : "Removed"}</span></div><p className="description">{model.description || "Creator-published AI model"}</p><div className="badges">{model.priceInr && <span className="badge">UPI ₹{Number(model.priceInr).toLocaleString("en-IN")}</span>}{model.license && <span className="badge">{model.license}</span>}{model.verification && <span className="badge">{model.verification.status}</span>}</div><button className="ghost" disabled={busy} onClick={() => onToggleModel(model)}>{model.active ? "Remove model" : "Restore model"}</button></div>)}</div>}<div className="section-heading dashboard-subheading"><div><p className="eyebrow">INR EARNINGS</p><h3>Payment ledger</h3></div><span className="meta">Pending payout: {rupees(stats.fiatCreatorNetPaise)}</span></div>{data.recentFiat.length === 0 ? <p className="meta">No verified INR sales yet.</p> : <div className="earnings-list">{data.recentFiat.map((row) => <div className="earning-row" key={`${row.modelId}-${row.createdAt}`}><span>Model #{row.modelId}</span><strong>{rupees(row.creatorPaise)}</strong><span className="badge">{row.status}</span></div>)}</div>}</section>;
}

function AdminConsole({ token, role, run, busy, note }) {
  const [data, setData] = useState({ overview: null, automation: null, identities: [], verifications: [], reports: [], roles: [] }), [error, setError] = useState(null), [newRole, setNewRole] = useState({ subject: "", role: "moderator", notes: "" });
  const adminFetch = async (path, options = {}) => { const response = await fetch(`${API}${path}`, { credentials: "include", ...options, headers: { ...jsonHeaders(token), ...(options.headers || {}) } }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "Admin request failed"); return result; };
  const load = useCallback(async () => { setError(null); try { const [overview, automation, identities, verifications, reports, roles] = await Promise.all([adminFetch("/api/admin/overview"), adminFetch("/api/admin/automation"), adminFetch("/api/admin/creator-identities?status=pending_review"), adminFetch("/api/admin/model-verifications?status=pending_review"), role === "reviewer" ? Promise.resolve({ reports: [] }) : adminFetch("/api/admin/reports"), role === "admin" ? adminFetch("/api/admin/roles") : Promise.resolve({ roles: [] })]); setData({ overview, automation, identities: identities.identities || [], verifications: verifications.verifications || [], reports: reports.reports || [], roles: roles.roles || [] }); } catch (e) { setError(e.message); } }, [token, role]);
  useEffect(() => { load(); }, [load]);
  const reviewIdentity = (item, status) => run(async () => { const reason = status === "rejected" ? window.prompt("Reason for rejecting this identity case?") : "Identity evidence reviewed by Atlas administrator"; if (status === "rejected" && !reason) return; await adminFetch(`/api/admin/creator-identities/${encodeURIComponent(item.wallet)}/review`, { method: "POST", body: JSON.stringify({ status, reason }) }); note(`Identity case ${status}`); load(); });
  const reviewEvidence = (item, status) => run(async () => { const notes = status === "rejected" ? window.prompt("Reason for rejecting this evidence?") : "Licence/provenance evidence reviewed by Atlas administrator"; if (status === "rejected" && !notes) return; await adminFetch(`/api/admin/model-evidence/${item.id}/review`, { method: "POST", body: JSON.stringify({ status, notes }) }); note(`Evidence ${status}`); load(); });
  const reviewProvenance = (item, status) => run(async () => { const reason = status === "rejected" ? window.prompt("Reason for rejecting provenance?") : "Provenance reviewed by Atlas administrator"; if (status === "rejected" && !reason) return; await adminFetch(`/api/admin/model-verifications/${item.id}/provenance-review`, { method: "POST", body: JSON.stringify({ status, reason }) }); note(`Provenance ${status}`); load(); });
  const reviewModel = (item, status) => run(async () => { const reason = status === "rejected" ? window.prompt("Reason for rejecting this model?") : "Model verification reviewed by Atlas administrator"; if (status === "rejected" && !reason) return; await adminFetch(`/api/admin/model-verifications/${item.id}/review`, { method: "POST", body: JSON.stringify({ status, reason }) }); note(`Model verification ${status}`); load(); });
  const reviewReport = (item, action) => run(async () => { const reason = window.prompt(`Reason for ${action}?`); if (!reason) return; await adminFetch(`/api/admin/reports/${item.id}/review`, { method: "POST", body: JSON.stringify({ action, reason }) }); note(`Report ${action} applied`); load(); });
  const grantRole = (event) => { event.preventDefault(); run(async () => { await adminFetch("/api/admin/roles", { method: "POST", body: JSON.stringify(newRole) }); setNewRole({ subject: "", role: "moderator", notes: "" }); note("Admin role granted"); load(); }); };
  const revokeRole = (subject) => run(async () => { if (!window.confirm(`Revoke the role for ${subject}?`)) return; await adminFetch(`/api/admin/roles/${encodeURIComponent(subject)}`, { method: "DELETE" }); note("Admin role revoked"); load(); });
  if (error) return <section className="admin-console"><div className="section-heading"><div><p className="eyebrow">ATLAS ADMIN</p><h2>Moderation console</h2></div><button className="ghost" onClick={load}>Retry</button></div><p className="error">{error}</p></section>;
  if (!data.overview) return <section className="admin-console"><p className="meta">Loading admin queues…</p></section>;
  const counts = data.overview.counts || {}, automation = data.automation || {};
  return <section className="admin-console"><div className="section-heading"><div><p className="eyebrow">ATLAS ADMIN</p><h2>Moderation console</h2><p className="hint">Role: {role}. Review creator attestation and moderation signals; do not treat them as automatic legal ownership proof.</p></div><button className="ghost" disabled={busy} onClick={load}>Refresh queues</button></div><section className="automation-panel"><div><p className="eyebrow">HYBRID MODERATION</p><h3>{automation.enabled ? "Atlas System Bot is active" : "Atlas System Bot is disabled"}</h3><p className="hint">The bot scans uploads, checks provenance, approves only low-risk standard listings, and routes risky cases to human review. It cannot approve KYC/evidence, take down models, grant roles, or move payments.</p></div><div className="automation-badges"><span className="badge">Actor: {automation.actor || "system:atlas-bot"}</span><span className="badge">Low-risk approval: {automation.capabilities?.lowRiskModelApproval ? "on" : "off"}</span><span className="badge">Report triage: {automation.capabilities?.reportTriage ? "on" : "off"}</span><span className="badge">Human gates: on</span></div></section><div className="stats admin-stats"><div><strong>{counts.pendingIdentity || 0}</strong><span>Identity cases</span></div><div><strong>{counts.pendingVerifications || 0}</strong><span>Model reviews</span></div><div><strong>{counts.pendingEvidence || 0}</strong><span>Evidence files</span></div><div><strong>{counts.openReports || 0}</strong><span>Open reports</span></div><div><strong>{counts.activeTakedowns || 0}</strong><span>Active takedowns</span></div></div><div className="admin-grid"><section className="admin-queue"><div className="section-heading"><h3>Identity/KYC cases</h3><span className="meta">{data.identities.length}</span></div>{data.identities.length === 0 ? <p className="meta">No pending identity cases.</p> : data.identities.map((item) => <article className="admin-item" key={item.wallet}><strong>{item.wallet}</strong><p className="meta">{item.country} · {item.provider} · document hash {item.documentSha256 || "not uploaded"}</p><div className="row"><button disabled={busy} onClick={() => reviewIdentity(item, "verified")}>Verify identity</button><button className="ghost" disabled={busy} onClick={() => reviewIdentity(item, "rejected")}>Reject</button></div></article>)}</section><section className="admin-queue"><div className="section-heading"><h3>Model verification</h3><span className="meta">{data.verifications.length}</span></div>{data.verifications.length === 0 ? <p className="meta">No pending model verifications.</p> : data.verifications.map((item) => <article className="admin-item" key={item.id}><strong>{item.id}</strong><p className="meta">Creator {item.creator} · {item.license} · identity {item.identityStatus} · provenance {item.provenanceStatus} · scan {item.scanStatus}</p>{item.provenanceStatus !== "passed" && <div className="row"><button disabled={busy} onClick={() => reviewProvenance(item, "passed")}>Pass provenance</button><button className="ghost" disabled={busy} onClick={() => reviewProvenance(item, "rejected")}>Reject provenance</button></div>}{(item.evidence || []).map((evidence) => <div className="evidence-row" key={evidence.id}><span>{evidence.kind}: {evidence.fileName}</span><span className="badge">{evidence.status}</span>{evidence.status === "pending_review" && <><button className="ghost" disabled={busy} onClick={() => reviewEvidence(evidence, "approved")}>Approve evidence</button><button className="ghost" disabled={busy} onClick={() => reviewEvidence(evidence, "rejected")}>Reject evidence</button></>}</div>)}<div className="row"><button disabled={busy} onClick={() => reviewModel(item, "approved")}>Approve model</button><button className="ghost" disabled={busy} onClick={() => reviewModel(item, "rejected")}>Reject model</button></div></article>)}</section><section className="admin-queue"><div className="section-heading"><h3>User reports</h3><span className="meta">{data.reports.length}</span></div>{data.reports.length === 0 ? <p className="meta">No reports yet.</p> : data.reports.map((item) => <article className="admin-item" key={item.id}><strong>Model #{item.modelId} · {item.reason}</strong><p>{item.details || "No additional details"}</p><p className="meta">Reported by {item.reporter} · {item.status} · bot: {item.automatedAction || "queued_for_review"}</p>{item.status === "open" && <div className="row"><button disabled={busy} onClick={() => reviewReport(item, "takedown")}>Takedown</button><button className="ghost" disabled={busy} onClick={() => reviewReport(item, "dismiss")}>Dismiss</button><button className="ghost" disabled={busy} onClick={() => reviewReport(item, "resolve")}>Resolve</button></div>}</article>)}</section></div>{role === "admin" && <section className="admin-roles"><div className="section-heading"><div><h3>Admin roles</h3><p className="hint">The bootstrap wallet from ADMIN_WALLET is the first administrator. Grant only trusted, reviewed accounts.</p></div></div><form className="row" onSubmit={grantRole}><input required placeholder="Wallet address or verified email" value={newRole.subject} onChange={(e) => setNewRole({ ...newRole, subject: e.target.value })} aria-label="Admin role subject" /><select value={newRole.role} onChange={(e) => setNewRole({ ...newRole, role: e.target.value })} aria-label="Admin role"><option value="moderator">Moderator</option><option value="reviewer">Reviewer</option><option value="admin">Administrator</option></select><input placeholder="Notes" value={newRole.notes} onChange={(e) => setNewRole({ ...newRole, notes: e.target.value })} aria-label="Admin role notes" /><button disabled={busy}>Grant role</button></form>{data.roles.map((item) => <div className="role-row" key={item.subject}><span>{item.subject}</span><span className="badge">{item.role}</span>{!item.revokedAt && <button className="ghost" disabled={busy} onClick={() => revokeRole(item.subject)}>Revoke</button>}</div>)}</section>}</section>;
}

function CommunityPanel({ token, run, busy, note }) {
  const [posts, setPosts] = useState([]), [selected, setSelected] = useState(null), [replies, setReplies] = useState([]), [form, setForm] = useState({ title: "", body: "", category: "General" }), [reply, setReply] = useState(""), [loading, setLoading] = useState(true), [error, setError] = useState(null);
  const loadPosts = useCallback(async () => { setLoading(true); try { const response = await fetch(`${API}/api/community/posts`, { credentials: "include", headers: jsonHeaders(token) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "Unable to load community posts"); setPosts(result.posts || []); } catch (e) { setError(e.message); } finally { setLoading(false); } }, [token]);
  useEffect(() => { loadPosts(); }, [loadPosts]);
  const openPost = async (post) => { setSelected(post); const response = await fetch(`${API}/api/community/posts/${post.id}/replies`, { credentials: "include", headers: jsonHeaders(token) }); const result = await response.json(); if (response.ok) setReplies(result.replies || []); };
  const createPost = (event) => { event.preventDefault(); run(async () => { const response = await post("/api/community/posts", token, form), result = await response.json(); if (!response.ok) throw new Error(result.error || "Could not publish post"); setPosts((old) => [result.post, ...old]); setForm({ title: "", body: "", category: "General" }); note("Community post published"); }); };
  const toggleLike = (post) => run(async () => { const response = await fetch(`${API}/api/community/posts/${post.id}/like`, { method: post.liked ? "DELETE" : "POST", credentials: "include", headers: jsonHeaders(token) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "Could not update like"); setPosts((old) => old.map((item) => item.id === post.id ? { ...item, liked: result.liked, likeCount: Math.max(0, item.likeCount + (result.liked ? 1 : -1)) } : item)); });
  const addReply = (event) => { event.preventDefault(); if (!selected) return; run(async () => { const response = await post(`/api/community/posts/${selected.id}/replies`, token, { body: reply }), result = await response.json(); if (!response.ok) throw new Error(result.error || "Could not add reply"); setReplies((old) => [...old, result.reply]); setPosts((old) => old.map((item) => item.id === selected.id ? { ...item, replyCount: item.replyCount + 1 } : item)); setSelected((old) => old ? { ...old, replyCount: old.replyCount + 1 } : old); setReply(""); }); };
  return <section className="community"><div className="section-heading"><div><p className="eyebrow">ATLAS COMMUNITY</p><h2>Learn, share, and build together</h2><p className="hint">Discuss models, Indian MSME use cases, integrations, and creator opportunities.</p></div><button className="ghost" disabled={busy} onClick={loadPosts}>Refresh</button></div>{token ? <form className="community-compose" onSubmit={createPost}><input required maxLength={120} placeholder="Post title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} aria-label="Post title" /><select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} aria-label="Post category"><option>General</option><option>Model showcase</option><option>MSME</option><option>Help</option><option>Jobs</option></select><textarea required maxLength={2500} rows={3} placeholder="Start a useful conversation…" value={form.body} onChange={(e) => setForm({ ...form, body: e.target.value })} aria-label="Post body" /><button disabled={busy}>Publish post</button></form> : <div className="notice">Sign in to publish posts, reply, or like community discussions.</div>}{error && <p className="error">{error}</p>}{loading ? <p className="meta">Loading community…</p> : posts.length === 0 ? <p className="meta">No discussions yet. Start the first Atlas conversation.</p> : <div className="community-layout"><div className="community-feed">{posts.map((postItem) => <article className={`community-post ${selected?.id === postItem.id ? "selected" : ""}`} key={postItem.id} onClick={() => openPost(postItem)}><div className="post-author"><div className="avatar">{postItem.author?.avatarUrl ? <img src={postItem.author.avatarUrl} alt="" /> : <span>{(postItem.author?.displayName || "A").slice(0, 1).toUpperCase()}</span>}</div><div><strong>{postItem.author?.displayName || "Atlas member"}</strong><span className="meta"> · {new Date(postItem.createdAt).toLocaleString()}</span></div><span className="badge post-category">{postItem.category}</span></div><h3>{postItem.title}</h3><p>{postItem.body}</p><div className="post-actions"><button className="link-button" disabled={!token} onClick={(event) => { event.stopPropagation(); toggleLike(postItem); }}>{postItem.liked ? "♥" : "♡"} {postItem.likeCount}</button><span className="meta">{postItem.replyCount} repl{postItem.replyCount === 1 ? "y" : "ies"}</span></div></article>)}</div>{selected && <aside className="community-thread"><div className="section-heading"><h3>{selected.title}</h3><button className="link-button" onClick={() => setSelected(null)}>Close</button></div><p className="meta">Replies to {selected.author?.displayName || "Atlas member"}</p>{replies.length === 0 ? <p className="meta">No replies yet.</p> : <div className="reply-list">{replies.map((item) => <div className="reply" key={item.id}><strong>{item.author?.displayName || "Atlas member"}</strong><p>{item.body}</p></div>)}</div>}{token && <form className="reply-form" onSubmit={addReply}><textarea required maxLength={1500} rows={3} placeholder="Write a helpful reply…" value={reply} onChange={(e) => setReply(e.target.value)} aria-label="Reply" /><button disabled={busy}>Reply</button></form>}</aside>}</div>}</section>;
}

function UsagePanel({ token }) {
  const [usage, setUsage] = useState(null);
  useEffect(() => { fetch(`${API}/api/usage`, { credentials: "include", headers: jsonHeaders(token) }).then((response) => response.ok ? response.json() : null).then(setUsage).catch(() => {}); }, [token]);
  if (!usage) return null;
  return <section className="usage"><p className="eyebrow">TRANSPARENT USAGE</p><h2>Your Atlas activity</h2><div className="stats"><div><strong>{usage.calls}</strong><span>Total inference calls</span></div><div><strong>{usage.successful}</strong><span>Successful calls</span></div><div><strong>{usage.calls ? Math.round((usage.successful / usage.calls) * 100) : 0}%</strong><span>Success rate</span></div></div></section>;
}
